mapper.select:

SELECT member_id	/*MemberMapper.selMemberId (회원가입 아이디 찾기)*/	
  FROM MEMBER
 WHERE 1 = 1
   AND member_name  = #{memberName}
   AND member_phone = #{memberPhone}

mapper.insert:
INSERT INTO MEMBER (	/*MemberMapper.insertMember (회원 등록)*/
      member_id
    , member_name
    , member_password
    , member_phone
    , member_email
    , business_number
    , ceo_name
    , company_name
    , company_phone
    , privacy_agree
    , privacy_agree_date
) VALUES (
      #{memberId}
    , #{memberName}
    , #{memberPassword}
    , #{memberPhone}
    , #{memberEmail}
    , #{businessNumber}
    , #{ceoName}
    , #{companyName}
    , #{companyPhone}
    , #{privacyAgree}
    , NOW()
)

mapper.update:
UPDATE MEMBER /*MemberMapper.updateMember (회원 정보수정)*/
member_name = #{memberName}, member_password = #{memberPassword}, member_phone = #{memberPhone}, member_email = #{memberEmail}, business_number = #{businessNumber}, ceo_name = #{ceoName}, company_name = #{companyName}, company_phone = #{companyPhone}, updated_at = NOW()
WHERE member_seq = #{memberSeq}
